head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vSECT_CHG_TP_CD = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vListProcsStatCd;
scwin.vAcptNo;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Item);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = '2';
        const sbmOptions = {
            id : "sbm_dts_Item",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Item=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Item.insertRow();
        await scwin.searchCode();
        const parentWin = $c.frame.path("../");
        const dstOjb = parentWin.dts_List_1;
        const row = dstOjb.getFocusedRowIndex();
        txb_ISUR_CD.setValue(dstOjb.getCellData(row, "ISUR_CD"));
        txb_COM_NM.setValue(dstOjb.getCellData(row, "ISUR_NM"));
        cmb_BFCHG_SECT_TP_CD.setValue(dstOjb.getCellData(row, "SECT_TP_CD")); // 변경전 소속부 : 원부 소속부코드
        cmb_AFCHG_SECT_TP_CD.setValue(dstOjb.getCellData(row, "NONSCHE_CD")); // 변경후 소속부 : 수시 소속부결과코드
        cmb_SECT_CHG_TP_CD.setValue("M"); // 변경구분 : 변경
        cmb_AFCHG_SECT_INVSTG_TP_CD.setValue("B"); // 소속부심사구분:수시

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05971.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05971.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        scwin.vSECT_CHG_TP_CD = dts_Item.getCellData(1, "SECT_CHG_TP_CD");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05971.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05971.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        // fn_parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05971.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_SECT_STRT_DD_onclick
 * @description img_SECT_STRT_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SECT_STRT_DD_onclick = function() {
    try {
        popUpCalendar2(edt_SECT_STRT_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05971.img_SECT_STRT_DD_onclick" });
    }
};

/**
 * @method
 * @name img_SECT_END_DD_onclick
 * @description img_SECT_END_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SECT_END_DD_onclick = function() {
    try {
        popUpCalendar2(edt_SECT_END_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05971.img_SECT_END_DD_onclick" });
    }
};

/**
 * @method
 * @name img_CHG_DD_onclick
 * @description img_CHG_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHG_DD_onclick = function() {
    try {
        popUpCalendar2(edt_CHG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05971.img_CHG_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05971.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
     */
    const arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }, {
        cid: "SECT_INVSTG_TP_CD",
        cnm: "cmb_AFCHG_SECT_INVSTG_TP_CD"
    }, {
        cid: "SECT_CHG_RSN_CD",
        cnm: "cmb_SECT_CHG_RSN"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                if (arrCid[i].cid === "VENT_TP_CD") {
                    if (dts_Cod.getCellData(j, "VALUE") === "10") {
                        strCbd = strCbd + "^-----------------------------------------------------";
                    }
                }
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name duplicateCheck
 * @description duplicate Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateCheck = async function() {
    url += "?SCREN_ID=" + "ULDSTF05971.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=checkDuplicate&inputMessageId=SECT_TYP_CHG_INOUT";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&CHG_DD=" + edt_CHG_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_DUP_CHK",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_DUP_CHK=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("fn_duplicate_check:"+dts_DUP_CHK.NameValue(1, "DUP_CHK"));
    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};

/**
 * @method
 * @name bfSectInvstgTpCd
 * @description bf Sect Invstg Tp Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfSectInvstgTpCd = async function() {
    url += "?SCREN_ID=" + "ULDSTF05971.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=SECT_TYP_CHG_INVSTG_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.scttypchg.bfchgsectinvstgtpcd.select";
    url += "&{P}param01=" + txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_bfSectInvstg",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_bfSectInvstg=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description 소속부 변경전 심사코드
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    // 소속부 변경전 심사코드
    await scwin.bfSectInvstgTpCd();
    dts_Item.setCellData(1, "JOB_TYPE", jobType);
    dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_234);
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", scwin.vSPOT_ISU_TRD_MKT_TP_CD);
    dts_Item.setCellData(1, "BFCHG_SECT_INVSTG_TP_CD", dts_bfSectInvstg.getCellData(1, "AFCHG_SECT_INVSTG_TP_CD"));
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SectionTypeChange.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_SECT_CHG_TP_CD.getValue() === "") {
        await $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD === 'N') {
        if (scwin.vSECT_CHG_TP_CD !== cmb_SECT_CHG_TP_CD.getValue()) {
            await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            // 심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
    }
    if (cmb_SECT_CHG_TP_CD.getValue() === "") {
        await $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (cmb_SECT_CHG_TP_CD.getValue() !== "N") {
        // 신규상장
        if (cmb_BFCHG_SECT_TP_CD.getValue() === "") {
            await $c.win.alert("[변경전 소속부] 항목값이  없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if (cmb_AFCHG_SECT_TP_CD.getValue() === "") {
        await $c.win.alert("[변경후 소속부]를 선택하세요.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if (edt_CHG_DD.getValue() === "") {
        await $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= edt_CHG_DD.getValue()) {
        await $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (edt_SECT_STRT_DD.getValue() === "") {
        if (edt_SECT_END_DD.getValue() !== "") {
            await $c.win.alert("[소속부유효시작일]을 입력하세요.");
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {
        if (edt_SECT_END_DD.getValue() === "") {
            await $c.win.alert("[소속부유효종료일]을 입력하세요.");
            edt_SECT_END_DD.focus();
            return false;
        }
        if (parseInt(edt_SECT_STRT_DD.getValue(), 10) > parseInt(edt_SECT_END_DD.getValue(), 10)) {
            await $c.win.alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    if (cmb_AFCHG_SECT_INVSTG_TP_CD.getValue() === "") {
        await $c.win.alert("[소속부 심사구분]를 선택하세요.");
        cmb_AFCHG_SECT_INVSTG_TP_CD.focus();
        return false;
    }
    if (cmb_BFCHG_SECT_TP_CD.getValue() === "4") {
        // 기술성장기업부
        if (cmb_AFCHG_SECT_TP_CD.getValue() === "2" || cmb_AFCHG_SECT_TP_CD.getValue() === "3") {
            await $c.win.alert("변경전 소속부가 기술성장기업부일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if (cmb_BFCHG_SECT_TP_CD.getValue() === "2" || // 벤처
        cmb_BFCHG_SECT_TP_CD.getValue() === "3") {
        // 중견
        if (cmb_AFCHG_SECT_TP_CD.getValue() === "4") {
            await $c.win.alert("변경전 소속부가 벤처나 중견일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (await scwin.duplicateCheck() === 'Y') {
            await $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
